import CustomizedButton from "components/common/CustomizedButton";
import React, { useEffect, useState } from "react";

import { Card, Form, Container, Row, Col } from "react-bootstrap";
import { useHistory, useParams } from "react-router";
import { isParameterPropertyDeclaration } from "typescript";
import auth from "utility/auth";
import { axios } from "utility/httpreq";
import notify from "utility/notify";

const EditRole = () => {
  const user = JSON.parse(localStorage.getItem("loggedInUser"));
  const history = useHistory();
  const params = useParams();
  const [isLoading, setIsLoading] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [permissions, setPermissions] = useState(null);
  const [rolePer, setRolePer] = useState({});
  const [formData, setFormData] = useState({
    name: "",
    permission: [],
  });

  useEffect(() => {
    const runAsync = async function () {
      try {
        setIsLoading(true);
        const per = await axios(true).get("/api/permission/list");
        setPermissions(per.data);
        const response = await axios(true).get("/api/role/" + params.id);
        const data = response.data;
        // setting permissions
        let rolePer = {};
        let perId = [];
        data.permission.forEach((per) => {
          perId.push(per);
          if (!rolePer[per]) {
            rolePer[per] = true;
          }
        });

        setRolePer(rolePer);

        setFormData({
          name: data?.name || "",
          permission: perId,
        });

        setIsLoading(false);
      } catch (error) {
        setIsLoading(false);
        notify.showError(error.response);
      }
    };

    runAsync();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      setIsUpdating(true);
      console.log("form data is", formData.permission);
      await axios(true).put("/api/role/" + params.id, formData);
      setIsUpdating(false);
      notify.showSuccess("Role edited successfully.");
    } catch (error) {
      setIsUpdating(false);
      console.log("error is", error);
    }
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    if (type == "checkbox") {
      if (checked) {
        setFormData({
          ...formData,
          permission: [...formData.permission, value],
        });
        setRolePer({ ...rolePer, [value]: true });
      } else {
        setFormData({
          ...formData,
          permission: formData.permission.filter((per) => {
            if (per !== value) {
              return per;
            }
          }),
        });
        let copyRolPer = { ...rolePer };
        delete copyRolPer[value];
        setRolePer(copyRolPer);
      }
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  let content = (
    <>
      <Container fluid>
        <Row>
          <Col md="8">
            <Card>
              <Card.Header>
                <Card.Title as="h4"> Edit Role</Card.Title>
              </Card.Header>
              <Card.Body>
                <Form onSubmit={handleSubmit}>
                  <Row>
                    <Col className="pr-1" md="12">
                      <Form.Group>
                        <label>Role Name</label>
                        <Form.Control
                          placeholder="Role Name"
                          type="text"
                          name="name"
                          value={formData.name}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>
                  <Row>
                    {permissions &&
                      permissions.map((per, index) => {
                        return (
                          <Col key={index} className="pr-1" md="4">
                            <Form.Group>
                              <Form.Check
                                onChange={handleChange}
                                value={per._id}
                                name="permission"
                                aria-label="option 1"
                                id={per._id}
                                checked={rolePer[per._id] ? true : false}
                                onClick={handleChange}
                              />
                              <label htmlFor={per._id}>{per.name}</label>
                            </Form.Group>
                          </Col>
                        );
                      })}
                  </Row>

                  <Row className="mt-3">
                    <Col className="pr-1" md="12">
                      {/* <Button
                    className="btn-fill pull-right"
                    type="submit"
                    variant="info"
                  >
                    Submit
                  </Button> */}
                      <CustomizedButton
                        isDisabled={isUpdating}
                        enabledLabel="Update"
                        disabledLabel="Updating..."
                        classNames="btn-fill pull-right"
                      />
                    </Col>
                  </Row>

                  <div className="clearfix"></div>
                </Form>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );

  if (auth(user)?.isRole("Admin")) {
    return isLoading ? <p>Loading...</p> : content;
  } else {
    return <Redirect to="/admin/dashboard" />;
  }
};

export default EditRole;
