import React, { useState, useEffect, useRef } from "react";
import { useLocation, Switch, Redirect, Route } from "react-router-dom";
import AdminNavbar from "components/Navbars/AdminNavbar";
import Footer from "components/Footer/Footer";
import Sidebar from "components/Sidebar/Sidebar";
import { Modal, Card, Form, Row, Col } from "react-bootstrap";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faPhone, faTimes } from "@fortawesome/fontawesome-free-solid";
import routes from "routes.js";
import sidebarImage from "assets/img/sidebar-3.jpg";
import AddUser from "views/AddUser";
import EditUser from "views/EditUser";
import NotFound from "views/NotFound";
import AddAgeGroup from "views/Data/AgeGroup/AddAgeGroup";
// chat required imports
import { connect } from "react-redux";

import EditAgeGroup from "views/Data/AgeGroup/EditAgeGroup";
import AddCallType from "views/Data/CallType/AddCallType";
import EditCallType from "views/Data/CallType/EditCallType";
import AddShift from "views/Data/Shift/AddShift";
import EditShift from "views/Data/Shift/EditShift";
import AddRole from "views/Data/Roles/AddRole";
import EditRole from "views/Data/Roles/EditRole";

import CustomizedButton from "components/common/CustomizedButton";
import { isSelected } from "helpers/array.helper";
import { socketConnect } from "redux/action/socket";
import { initCall } from "redux/action/socket";
import { answerCall } from "redux/action/socket";
import { setCallModal } from "redux/action/socket";
import { declineCall } from "redux/action/socket";
import BlogAdd from "views/Blog/BlogAdd";
import BlogEdit from "views/Blog/BlogEdit";
import { stopTimer } from "redux/action/socket";
import { muteMic } from "redux/action/socket";
import { setCall } from "redux/action/socket";
import { getFirstLetter } from "helpers";

// chat required imports
let defaultForm = {
  facilitator: "",
  customerUserName: "",
  callFrom: "",
  firstname: "",
  middlename: "",
  lastname: "",
  address: "",
  province: "",
  email: "",
  phone: "",
  gender: "",
  ageGroup: "",
  shift: "",
  callType: [],
};

function AdminLayout(props) {
  // console.log(document.getElementById('outgoingCall'))
  const user = JSON.parse(localStorage.getItem("loggedInUser"));
  const [image, setImage] = React.useState(sidebarImage);
  const [color, setColor] = React.useState("white");
  const [mute, setMute] = React.useState(false);
  const [showModal, setShowModal] = React.useState(false);
  const [hasImage, setHasImage] = React.useState(true);
  const [loading, setLoading] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const location = useLocation();
  const mainPanel = React.useRef(null);

  //Chat Required Stuff
  const [formData, setFormData] = useState(defaultForm);
  const [data, setData] = useState({});

  const getBrandText = () => {
    for (let i = 0; i < routes.length; i++) {
      if (location.pathname.indexOf(routes[i].layout + routes[i].path) > -1) {
        return routes[i].name;
      }
    }

    return location.pathname.split("/").pop();
  };

  React.useEffect(() => {
    document.documentElement.scrollTop = 0;
    document.scrollingElement.scrollTop = 0;
    mainPanel.current.scrollTop = 0;
    if (
      window.innerWidth < 993 &&
      document.documentElement.className.indexOf("nav-open") !== -1
    ) {
      document.documentElement.classList.toggle("nav-open");
      var element = document.getElementById("bodyClick");
      element.parentNode.removeChild(element);
    }
  }, [location]);

  const loggedInUser = localStorage.getItem("loggedInUser");
  // Chat and Call codes

  useEffect(() => {
    console.log("status is from use effect ", props?.io?.call?.status);
    if (props?.io?.call?.status === "disconnected") {
      props.stopTimer(props?.io?.call?.reference);
    }
  }, [props?.io?.call?.status]);

  useEffect(() => {
    if (!props.io.connected) {
      props.socketConnect();
    }
  }, [props.io.connected]);

  const handleChange = (e) => {
    const { value, name } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const getRoutes = (routes) => {
    return routes.map((prop, key) => {
      if (prop.layout === "/admin") {
        return (
          <Route
            path={prop.layout + prop.path}
            render={(props) => {
              props.initCall = initCall;
              return <prop.component {...props} />;
            }}
            key={key}
            exact
          />
        );
      }
    });
  };

  const getPhoneButton = (data) => {
    let content;
    // if i am not initiator show call button
    if (!data.isInitiator && data.status == "calling") {
      console.log("connect button");
      content = (
        <button
          type="button"
          onClick={() =>
            props?.answerCall(
              props?.io?.socket,
              props?.io?.call?.signal,
              props?.io?.call?.from
            )
          }
          className="mr-3 ml-3 btn-circle btn-start-call d-md-inline-block btn"
        >
          {/* <FontAwesomeIcon icon="fas fa-phone-alt" /> */}
          <FontAwesomeIcon icon={faPhone} />
        </button>
      );
    }

    return content;
  };

  const getMuteButton = (data) => {
    let content;
    // if call is connected send mute button
    if (data.status === "connected") {
      content = (
        <button
          className={`mr-3 ml-3 btn-circle d-md-inline-block btn btn-mute-off ${
            mute ? "btn-mute" : ""
          }`}
          onClick={() => {
            setMute(!mute);
            props?.muteMic(props?.io?.call?.localStream);
          }}
        >
          <i class="nc-icon nc-audio-92"></i>
        </button>
      );
    }
    return content;
  };

  const getDeclineButton = (data) => {
    let content;
    if (data.status != "disconnected") {
      content = (
        <button
          type="button"
          onClick={() => {
            setMute(false);
            props.declineCall(
              props?.io?.socket,
              props?.io?.call?.peer,
              props?.io?.call?.localStream,
              user._id,
              props?.io?.call?.isInitiator
                ? props?.io?.call?.to
                : props?.io?.call?.from
            );
          }}
          className="mr-3 ml-3 btn-circle btn-end-call d-md-inline-block btn"
        >
          {/* <FontAwesomeIcon icon="fas fa-phone-alt" /> */}
          <FontAwesomeIcon icon={faTimes} />
        </button>
      );
    }
    return content;
  };

  const handleCloseModal = (type) => {
    if (type === "yes") {
      if (props?.io?.call?.peer) {
        props?.io?.call?.peer.close();
        if (props?.io?.call?.localStream) {
          props?.io?.call?.localStream.getTracks().forEach(function (track) {
            track.stop();
          });
        }
      }
      // props?.setCallModal(false);
      props?.setCall({
        showModal: false,
        status: null,
        duration: "",
        from: null,
        to: null,
        peer: null,
        localStream: null,
        isInitiator: null,
      });
    }
    setShowModal(false);
  };
  return (
    <>
      <div className="wrapper">
        <Sidebar color={color} image={hasImage ? image : ""} routes={routes} />
        <div className="main-panel" ref={mainPanel}>
          {/* <Button
            className="btn-fill btn-wd"
            variant="info"
            onClick={() => setShowModal(true)}
          >
            Launch Modal
          </Button> */}
          <AdminNavbar />
          <div className="content" id={getBrandText()}>
            {loggedInUser ? (
              <>
                <Switch>
                  {getRoutes(routes)}
                  <Route
                    exact
                    path={"/admin/user/add"}
                    component={AddUser}
                  ></Route>{" "}
                  <Route
                    exact
                    path={"/admin/user/edit/:id"}
                    component={EditUser}
                  ></Route>
                  {/* cage group */}
                  <Route
                    exact
                    path={"/admin/agegroup/add"}
                    component={AddAgeGroup}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/agegroup/edit/:id"}
                    component={EditAgeGroup}
                  ></Route>
                  {/* Call type Route */}
                  <Route
                    exact
                    path={"/admin/calltype/add"}
                    component={AddCallType}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/calltype/edit/:id"}
                    component={EditCallType}
                  ></Route>
                  {/* Shift Route */}
                  <Route
                    exact
                    path={"/admin/shift/add"}
                    component={AddShift}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/shift/edit/:id"}
                    component={EditShift}
                  ></Route>
                  {/* Role Route */}
                  <Route
                    exact
                    path={"/admin/role/add"}
                    component={AddRole}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/role/edit/:id"}
                    component={EditRole}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/blogs/add"}
                    component={BlogAdd}
                  ></Route>
                  <Route
                    exact
                    path={"/admin/blogs/edit/:id"}
                    component={BlogEdit}
                  ></Route>
                  {/* <Route


                    exact
                    path={"/admin/call/voice-call"}
                    component={VoiceCall}
                  ></Route> */}
                  <Route component={NotFound}></Route>
                </Switch>
              </>
            ) : (
              <>
                <Switch>
                  <Redirect to="/auth/login" />
                </Switch>
              </>
            )}
          </div>
          <Footer />
        </div>
      </div>

      {/* Mini Modal */}
      <Modal
        className="modal-mini modal-primary call-modal"
        show={props?.io?.call?.showModal}
        onHide={() => props?.setCallModal(false)}
        backdrop="static"
      >
        <Modal.Body className="d-flex p-0">
          <div className="voice-call-page call-wrapper">
            <div className="call-header">
              <p className="font-weight-bold"> {props?.io?.call?.status} </p>
            </div>
            <div className="d-flex align-items-center py-1 flex-column call-body">
              <div className="position-relative">
                <div className="avatar-box bg-light-danger">
                  <span className="avatar-label">
                    {getFirstLetter(props?.io?.call?.callUser?.username)}
                  </span>
                </div>
              </div>
              <div className="flex-grow-1">
                <span className="chat-username-sm">
                  {props?.io?.call?.callUser?.username}
                </span>
                <div className="text-muted small text-center">
                  <strong> {props?.io?.call?.duration} </strong>
                </div>
              </div>
            </div>

            <div className="call-control-btns d-flex justify-content-center align-items-center w-100">
              {getMuteButton(props?.io?.call)}
              {getPhoneButton(props?.io?.call)}
              {getDeclineButton(props?.io?.call)}
            </div>
          </div>
          <Row>
            <Col md="12">
              <Card>
                <Card.Header className="d-flex justify-content-between">
                  <Card.Title as="h4"> Service Seeker Information </Card.Title>
                  <button
                    onClick={() => {
                      setShowModal(true);
                    }}
                    className="close"
                  >
                    <i class="nc-icon nc-simple-remove"></i>
                  </button>
                </Card.Header>

                <Card.Body>
                  {loading ? (
                    "loading..."
                  ) : (
                    <Form>
                      <Row>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label>First Name</label>
                            <Form.Control
                              placeholder="First Name"
                              type="text"
                              name="firstname"
                              value={formData?.firstname}
                              onChange={handleChange}
                              required
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label>Middle Name</label>
                            <Form.Control
                              placeholder="Middle Name"
                              type="text"
                              name="middlename"
                              value={formData?.middlename}
                              onChange={handleChange}
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label>Last Name</label>
                            <Form.Control
                              placeholder="Last Name"
                              type="text"
                              name="lastname"
                              value={formData?.lastname}
                              onChange={handleChange}
                              required
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                      </Row>
                      <Row>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label> Address </label>
                            <Form.Control
                              placeholder="Address"
                              onChange={handleChange}
                              value={formData.address}
                              type="text"
                              name="address"
                            ></Form.Control>
                          </Form.Group>
                        </Col>

                        <Col className="pr-3" md="4">
                          <Form.Group>
                            <label htmlFor="typeSelect">Province</label>
                            <select
                              required
                              onChange={handleChange}
                              name="province"
                              className="form-control"
                            >
                              <option>Province 1 </option>
                              <option>Province 2 </option>
                            </select>
                          </Form.Group>
                        </Col>
                      </Row>

                      <Row>
                        <Col className="pr-1" md="5">
                          <Form.Group>
                            <label htmlFor="exampleInputEmail1">
                              Email address
                            </label>
                            <Form.Control
                              placeholder="Email"
                              type="email"
                              name="email"
                              value={formData.email}
                              onChange={handleChange}
                              required
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-1" md="4">
                          <Form.Group>
                            <label htmlFor="exampleInputPhone">Phone</label>
                            <Form.Control
                              placeholder="Phone"
                              onChange={handleChange}
                              value={formData.phone}
                              type="text"
                              name="phone"
                            ></Form.Control>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="3">
                          <Form.Group>
                            <label htmlFor="typeSelect">Gender</label>
                            <select
                              required
                              name="gender"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              <option
                                selected={isSelected("Male", formData.gender)}
                                value="Male"
                              >
                                Male{" "}
                              </option>
                              <option
                                selected={isSelected("Female", formData.gender)}
                                value="Female"
                              >
                                Female{" "}
                              </option>
                              <option
                                selected={isSelected("Other", formData.gender)}
                                value="Other"
                              >
                                Other{" "}
                              </option>
                            </select>
                          </Form.Group>
                        </Col>
                      </Row>
                      <Row>
                        {/* <Col className="pr-3" md="3">
                          <Form.Group>
                            <label htmlFor="typeSelect">Age Group</label>
                            <select
                              required
                              name="ageGroup"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {data?.ageGroups?.map((ageGroup) => {
                                return (
                                  <option
                                    selected={isSelected(
                                      ageGroup._id,
                                      formData.ageGroup
                                    )}
                                    key={ageGroup._id}
                                    value={ageGroup._id}
                                  >
                                    {ageGroup?.title}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col> */}
                        <Col className="pr-3" md="3">
                          <Form.Group>
                            <label htmlFor="typeSelect">Shift</label>
                            <select
                              required
                              name="shift"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {data?.shifts?.map((shift) => {
                                return (
                                  <option key={shift._id} value={shift._id}>
                                    {shift?.title}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                        <Col className="pr-3" md="3">
                          <Form.Group>
                            <label htmlFor="typeSelect">Call Type</label>
                            <select
                              required
                              name="callType"
                              onChange={handleChange}
                              className="form-control"
                            >
                              <option></option>
                              {data?.callTypes?.map((callType) => {
                                return (
                                  <option
                                    key={callType._id}
                                    value={callType._id}
                                  >
                                    {callType?.title}
                                  </option>
                                );
                              })}
                            </select>
                          </Form.Group>
                        </Col>
                      </Row>

                      <Row className="mt-3">
                        <Col className="pr-1" md="12">
                          <CustomizedButton
                            isDisabled={
                              isSubmitting ||
                              [
                                "connected",
                                "calling",
                                "checking",
                                "failed",
                              ].includes(props?.call?.callStatus)
                            }
                            enabledLable="Submit"
                            disabledLable={
                              isSubmitting ? "Submitting..." : "Submit"
                            }
                          />
                        </Col>
                      </Row>

                      <div className="clearfix"></div>
                    </Form>
                  )}
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </Modal.Body>
      </Modal>

      {/* Mini Modal */}
      <Modal
        className="modal-mini modal-primary msg-modal"
        // show={props?.io?.call?.showModal}
        show={showModal}
        onHide={() => setShowModal(false)}
        backdrop="static"
      >
        <Modal.Body className="d-flex p-0">
          <Row>
            <Col md="12">
              <Card>
                <Card.Header className="d-flex justify-content-between">
                  <Card.Title as="h4">
                    {" "}
                    Are you sure. Your data will not be saved{" "}
                  </Card.Title>
                  <button
                    onClick={() => handleCloseModal("yes")}
                    className="btn btn-danger btn-sm"
                  >
                    ok
                  </button>
                  <button
                    onClick={() => handleCloseModal("no")}
                    className="btn btn-danger btn-sm"
                  >
                    No
                  </button>
                </Card.Header>
              </Card>
            </Col>
          </Row>
        </Modal.Body>
      </Modal>

      <video
        style={{
          visibility: "hidden",
          height: "0px",
          width: "0px",
        }}
        autoPlay={true}
        id="user-video"
      ></video>
      <video
        style={{
          visibility: "hidden",
          height: "0px",
          width: "0px",
        }}
        muted
        autoPlay={true}
        id="my-video"
      ></video>
      {/* End Modal */}
    </>
  );
}

const mapStateToProps = (state) => ({
  io: state.io,
  audio: state.audio,
});

const mapDispatchToProps = (dispatch) => ({
  socketConnect: () => dispatch(socketConnect()),
  answerCall: (socket, signal, from) =>
    dispatch(answerCall(socket, signal, from)),
  setCallModal: (val) => dispatch(setCallModal(val)),
  declineCall: (socket, peer, stream, from, to) =>
    dispatch(declineCall(socket, peer, stream, from, to)),
  stopTimer: (reference) => dispatch(stopTimer(reference)),
  muteMic: (stream) => dispatch(muteMic(stream)),
  setCall: (call) => dispatch(setCall(call)),
});
export default connect(mapStateToProps, mapDispatchToProps)(AdminLayout);
