import CustomizedButton from "components/common/CustomizedButton";
import React, { useEffect, useState } from "react";

import { Card, Form, Container, Row, Col } from "react-bootstrap";
import { useHistory, useParams } from "react-router";
import { isParameterPropertyDeclaration } from "typescript";
import auth from "utility/auth";
import { axios } from "utility/httpreq";
import notify from "utility/notify";

const EditShift = () => {
  const user = JSON.parse(localStorage.getItem("loggedInUser"));
  const history = useHistory();
  const params = useParams();
  const [isLoading, setIsLoading] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [roles, setRoles] = useState(null);
  const [formData, setFormData] = useState({
    title: "",
    start: "",
    startAbbreviation: "AM",
    end: "",
    endAbbreviation: "AM",
  });

  useEffect(() => {
    const runAsync = async function () {
      try {
        setIsLoading(true);
        const response = await axios(true).get("/api/shift/" + params.id);
        const data = response.data;
        setFormData({
          start: data?.start || "",
          startAbbreviation: data?.startAbbreviation || "",
          end: data?.end || "",
          endAbbreviation: data?.endAbbreviation || "",
        });
        setIsLoading(false);
      } catch (error) {
        setIsLoading(false);
        notify.showError(error.response);
      }
    };

    runAsync();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      setIsUpdating(true);
      await axios(true).put("/api/shift/" + params.id, formData);
      setIsUpdating(false);
      history.push("/admin/shift");
    } catch (error) {
      setIsUpdating(false);
      console.log("error is", error);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  let content = (
    <>
      <Container fluid>
        <Row>
          <Col md="8">
            <Card>
              <Card.Header>
                <Card.Title as="h4"> Add Age Group</Card.Title>
              </Card.Header>
              <Card.Body>
                <Form onSubmit={handleSubmit}>
                  <Row>
                    <Col className="pr-1" md="12">
                      <Form.Group>
                        <label>Shift Name</label>
                        <Form.Control
                          placeholder="shift name"
                          type="title"
                          name="title"
                          value={formData.title}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                  </Row>
                  <Row>
                    <Col className="pr-1" md="6">
                      <Form.Group>
                        <label>Start Time</label>
                        <Form.Control
                          placeholder="start time"
                          type="text"
                          name="start"
                          value={formData.start}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                    <Col className="pr-1" md="6">
                      <Form.Group>
                        <label htmlFor="typeSelect">Abbreviation</label>
                        <select
                          required
                          name="startAbbreviation"
                          className="form-control"
                          onChange={handleChange}
                        >
                          <option
                            selected={
                              formData.startAbbreviation == "AM" ? true : false
                            }
                            value="AM"
                          >
                            AM
                          </option>
                          <option
                            selected={
                              formData.startAbbreviation == "PM" ? true : false
                            }
                            value="PM"
                          >
                            PM
                          </option>
                        </select>
                      </Form.Group>
                    </Col>
                  </Row>
                  <Row>
                    <Col className="pr-1" md="6">
                      <Form.Group>
                        <label>End Time</label>
                        <Form.Control
                          placeholder="end time"
                          type="text"
                          name="end"
                          value={formData.end}
                          required
                          onChange={handleChange}
                        ></Form.Control>
                      </Form.Group>
                    </Col>
                    <Col className="pr-1" md="6">
                      <Form.Group>
                        <label htmlFor="typeSelect">Abbreviation</label>
                        <select
                          required
                          name="endAbbreviation"
                          className="form-control"
                          onChange={handleChange}
                        >
                          <option
                            selected={
                              formData.endAbbreviation == "AM" ? true : false
                            }
                            value="AM"
                          >
                            AM
                          </option>
                          <option
                            selected={
                              formData.endAbbreviation == "PM" ? true : false
                            }
                            value="PM"
                          >
                            PM
                          </option>
                        </select>
                      </Form.Group>
                    </Col>
                  </Row>
                  <Row className="mt-3">
                    <Col className="pr-1" md="12">
                      {/* <Button
                    className="btn-fill pull-right"
                    type="submit"
                    variant="info"
                  >
                    Submit
                  </Button> */}
                      <CustomizedButton
                        isDisabled={isUpdating}
                        enabledLabel="Update"
                        disabledLabel="Updating..."
                        classNames="btn-fill pull-right"
                      />
                    </Col>
                  </Row>

                  <div className="clearfix"></div>
                </Form>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );

  if (auth(user)?.isRole("Admin") || auth(user)?.isUserAllowed("view_user")) {
    return isLoading ? <p>Loading...</p> : content;
  } else {
    return <Redirect to="/admin/dashboard" />;
  }
};

export default EditShift;
