import React, { useState, useEffect } from "react";
import { Card, Table, Container, Row, Col } from "react-bootstrap";

import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";

import { faEdit, faTrash } from "@fortawesome/fontawesome-free-solid";
import { Link, Redirect } from "react-router-dom";

import auth from "utility/auth";
import notify from "utility/notify";
import { axios } from "utility/httpreq";
import useFetchData from "hooks/useFetchData";

const BlogList = () => {
  const { data: blogs, loading } = useFetchData("/api/blog/list");
  const user = JSON.parse(localStorage.getItem("loggedInUser"));
  let content = loading ? (
    <p>Loading....</p>
  ) : (
    <>
      <Container fluid>
        <Row className="mb-2">
          <Col md="12">
            <div className="add-btn text-right">
              <Link to="/admin/blogs/add" className="btn btn-brand">
                Add
              </Link>
            </div>
          </Col>
        </Row>
        <Row>
          <Col md="12">
            <Card className="strpied-tabled-with-hover">
              <Card.Header>
                <Card.Title as="h4"> Blog List </Card.Title>
                {/* <p className="card-category">
                  Here is a subtitle for this table
                </p> */}
              </Card.Header>
              <Card.Body className="table-full-width table-responsive px-0">
                <Table className="table-hover table-striped">
                  <thead>
                    <tr>
                      <th className="border-0">SN</th>
                      <th className="border-0">Title</th>
                      <th className="border-0">Subtitle</th>
                      <th className="border-0">Short Description</th>
                      <th className="border-0">Published</th>
                      <th className="border-0">Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {/* <tr>
                          <td> 1 </td>
                          <td> Harry Kane</td>
                          <td> harrykane10@gmail.com</td>
                          <td> Active </td>
                          <td>Admin</td>
                          <td>
                            <Link to="/admin/user/edit" className="mr-3">
                              <FontAwesomeIcon icon={faEdit} />
                            </Link>
                            <Link to="" className="">
                              <FontAwesomeIcon icon={faTrash} />
                            </Link>
                          </td>
                        </tr> */}

                    {blogs &&
                      Array.isArray(blogs) &&
                      blogs.map((blog, index) => {
                        return (
                          <tr key={index}>
                            <td>{index + 1}</td>
                            <td>{blog.title}</td>
                            <td>{blog.subtitle}</td>
                            <td>{blog?.cardBody}</td>
                            <td>{blog.isPublished ? "Published" : "Unpublished"}</td>
                            <td>
                              <Link
                                to={"/admin/blogs/edit/" + blog._id}
                                className="mr-3"
                              >
                                <FontAwesomeIcon icon={faEdit} />
                              </Link>
                            </td>
                          </tr>
                        );
                      })}
                  </tbody>
                </Table>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
  if (auth(user)?.isRole("Admin") || auth(user)?.isUserAllowed("view_user")) {
    return content;
  } else {
    return <Redirect to="/admin/dashboard" />;
  }
};
export default BlogList;

